// src/checks/auth-redirects.ts
function concrete(base2, path) {
  return base2 + (path.startsWith("/") ? path : `/${path}`).replace(/\*\*/g, "golive/probe").replace(/\*/g, "golive");
}
var authRedirectsCheck = {
  id: "auth-redirects",
  title: "Auth redirects point at production",
  severity: "high",
  applies: (ctx) => Boolean(ctx.config.stack.auth),
  async run(ctx) {
    const auth8 = cap(ctx, "auth", "authConfig");
    if (!auth8) return skip(`auth provider ${ctx.config.stack.auth} has no auth-config capability (guided)`);
    const pre = await prereq(ctx, "auth");
    if (pre) return pre;
    const prod = await baseUrl(ctx);
    if (!prod) return blocked("deploy:production", "no production URL yet");
    let cfg2;
    try {
      cfg2 = await auth8.get(ctx);
    } catch (e) {
      return result("fail", "high", [`could not read auth settings: ${errMsg(e)}`], "Re-run verify; if it persists, check the auth provider with `golive doctor`.");
    }
    const problems = [];
    const evidence = [`production URL: ${prod}`, `site URL: ${cfg2.siteUrl ?? "(unset)"}`];
    if (!cfg2.siteUrl) problems.push("site URL is not set");
    else if (isLocalhost(cfg2.siteUrl)) problems.push(`site URL is localhost (${cfg2.siteUrl}): emails and OAuth will send production users to localhost`);
    else if (trimSlash(cfg2.siteUrl) !== prod) problems.push(`site URL ${cfg2.siteUrl} is not the production URL`);
    const paths = ctx.config.auth?.redirectPaths;
    if (paths?.length) {
      const uncovered = paths.filter((p) => !cfg2.redirectUrls.some((pat) => globMatch(pat, concrete(prod, p))));
      if (uncovered.length) problems.push(`redirect allowlist does not cover ${uncovered.map((p) => prod + p).join(", ")}`);
      else evidence.push(`redirect allowlist covers ${paths.map((p) => prod + p).join(", ")}`);
    } else {
      const onProd = cfg2.redirectUrls.filter((pat) => globMatch(pat, prod) || globMatch(pat, concrete(prod, "/**")) || trimSlash(pat).toLowerCase().startsWith(`${prod.toLowerCase()}/`));
      if (!onProd.length) problems.push(`redirect allowlist has no entry for ${prod}`);
      else evidence.push(`redirect allowlist covers ${prod} (${onProd.slice(0, 3).join(", ")})`);
    }
    const local = cfg2.redirectUrls.filter(isLocalhost);
    if (problems.length) {
      return result("fail", "high", [...problems, ...evidence], `Run \`golive plan\` and apply the auth-redirects step (sets site URL to ${prod} and adds ${prod}/** to the allowlist).`);
    }
    if (local.length) {
      return result("warn", "low", [`allowlist still includes localhost: ${local.join(", ")}`, ...evidence], "Fine for a shared dev project; for a production-only project remove localhost entries.");
    }
    return pass(evidence);
  }
};

// src/checks/auth.ts
var MIN_PASSWORD = 12;
var AUTH_EMAILS_PER_RUN = 4;
var RESEND_SMTP_HOST = "smtp.resend.com";
var isResendSmtp = (host) => (host ?? "").trim().toLowerCase() === RESEND_SMTP_HOST;
function appUsesAuth(ctx, provider) {
  return Boolean(ctx.detect.providers.auth?.includes(provider));
}
var authPolicyCheck = {
  id: "auth-policy",
  title: "Auth policy matches the app and the configured baseline",
  severity: "high",
  applies: (ctx) => Boolean(ctx.config.stack.auth),
  async run(ctx) {
    const provider = ctx.config.stack.auth;
    const auth8 = cap(ctx, "auth", "authConfig");
    if (!auth8) return skip(`auth provider ${provider} has no auth-config capability (guided)`);
    const pre = await prereq(ctx, "auth");
    if (pre) return pre;
    let cfg2;
    try {
      cfg2 = await auth8.get(ctx);
    } catch (e) {
      return result("fail", "high", [`could not read ${provider} auth settings: ${errMsg(e)}`], "Re-run verify; if it persists, check the auth provider with `golive doctor`.");
    }
    const issues = [];
    const evidence = [];
    const missing = [];
    const wantSignup = ctx.config.auth?.signup;
    if (cfg2.signupEnabled === void 0) missing.push("signup");
    else {
      evidence.push(`signup: ${cfg2.signupEnabled ? "open" : "closed"}`);
      if (!cfg2.signupEnabled && wantSignup === true) {
        issues.push({
          severity: "high",
          line: "signup is closed although golive.yaml asks for `auth.signup: true`: new users cannot register",
          fix: "Re-run `plan` + `apply` (the `auth:settings` step writes it), or set `auth.signup: false` if this app really takes no new users."
        });
      } else if (!cfg2.signupEnabled && wantSignup === void 0 && appUsesAuth(ctx, provider)) {
        issues.push({
          severity: "medium",
          line: `signup is closed while this app's code uses ${provider} auth and golive.yaml does not say whether it takes new users: any sign-up path in the app would fail`,
          fix: `Say what this app needs in golive.yaml: \`auth.signup: true\` to take new users (then \`plan\` + \`apply\`), or \`auth.signup: false\` to confirm that closing signup is intended.`
        });
      } else if (!cfg2.signupEnabled && wantSignup === false) {
        evidence.push("signup is closed as configured (auth.signup: false)");
      } else if (cfg2.signupEnabled && wantSignup === false) {
        issues.push({
          severity: "medium",
          line: "signup is open although golive.yaml says `auth.signup: false`: the setting is not in effect, so the provider still takes new users",
          fix: "Re-run `plan` + `apply` (the `auth:settings` step writes it), or set `auth.signup: true` if this app does take new users."
        });
      }
    }
    const requireEmailConfirm = ctx.config.auth?.requireEmailConfirm;
    if (cfg2.emailConfirmRequired === void 0) missing.push("email confirmation");
    else {
      evidence.push(`email confirmation: ${cfg2.emailConfirmRequired ? "required" : "off"}`);
      if (!cfg2.emailConfirmRequired && requireEmailConfirm === true) {
        issues.push({
          severity: "high",
          line: "email confirmation is off although golive.yaml asks for `auth.requireEmailConfirm: true`: signups are not proven to belong to a real inbox",
          fix: `Re-run \`plan\` + \`apply\` (the \`auth:settings\` step writes it), or remove \`auth.requireEmailConfirm\` if confirmation is not wanted.`
        });
      } else if (!cfg2.emailConfirmRequired && ctx.config.targets.includes("production")) {
        issues.push({
          severity: "medium",
          line: "email confirmation is off in production: signups are not proven to belong to a real inbox",
          fix: `Require confirmation with \`auth.requireEmailConfirm: true\` in golive.yaml, then \`plan\` + \`apply\`; set it to \`false\` explicitly to accept the risk.`
        });
      }
    }
    const floor = ctx.config.auth?.passwordMinLength;
    if (cfg2.minPasswordLength === void 0) missing.push("password minimum length");
    else {
      evidence.push(`password minimum length: ${cfg2.minPasswordLength}`);
      if (typeof floor === "number" && cfg2.minPasswordLength < floor) {
        issues.push({
          severity: "high",
          line: `password minimum length is ${cfg2.minPasswordLength}, below the floor golive.yaml asks for (auth.passwordMinLength: ${floor})`,
          fix: `Re-run \`plan\` + \`apply\` (the \`auth:settings\` step sets it), or lower \`auth.passwordMinLength\` to what the provider allows.`
        });
      } else if (cfg2.minPasswordLength < MIN_PASSWORD) {
        issues.push({
          severity: "medium",
          line: `password minimum length is ${cfg2.minPasswordLength}; ${MIN_PASSWORD} or more is the safe baseline`,
          fix: `Set \`auth.passwordMinLength: ${MIN_PASSWORD}\` (or higher) in golive.yaml, then \`plan\` + \`apply\`, or set it in the ${provider} dashboard.`
        });
      }
    }
    if (!cfg2.smtp) missing.push("auth email (SMTP)");
    else {
      evidence.push(cfg2.smtp.configured ? `auth email: custom SMTP${isResendSmtp(cfg2.smtp.host) ? " via Resend" : ""}${cfg2.smtp.host ? ` (${cfg2.smtp.host})` : ""}` : "auth email: provider built-in mailer");
      if (cfg2.smtp.configured) {
        if (cfg2.smtp.senderEmail) evidence.push(`auth email sender: ${cfg2.smtp.senderEmail}`);
        evidence.push("the provider never returns the SMTP password, so this reads the settings back, not a delivery");
      } else if (ctx.config.auth?.smtp === "resend") {
        issues.push({
          severity: "medium",
          line: `golive.yaml asks for the app's email provider (\`auth.smtp: resend\`) but auth emails still go through ${provider}'s built-in mailer, which allows roughly one accepted send per window \u2014 the recovery journey alone needs four`,
          fix: `Re-run \`plan\` + \`apply\` (the \`auth:smtp\` step writes the custom SMTP from a sending key golive issues, and raises the auth email rate limit with it), then re-run verify.`
        });
      } else if (ctx.config.auth?.smtp !== "provider") {
        issues.push({
          severity: "medium",
          line: `auth emails go through ${provider}'s built-in mailer, which is rate-limited and meant for testing: its limit can refuse the sends an auth journey needs (HTTP 429, roughly one accepted send per window)`,
          fix: `Set \`auth.smtp: resend\` in golive.yaml and re-run \`plan\` + \`apply\` (the \`auth:smtp\` step writes the custom SMTP from a sending key golive issues), configure custom SMTP in the ${provider} dashboard, or accept the built-in mailer with \`auth.smtp: provider\`.`
        });
      }
    }
    if (cfg2.emailRateLimitPerHour === void 0) missing.push("rate limit");
    else {
      evidence.push(`rate limit: ${cfg2.emailRateLimitPerHour} auth emails/hour (the provider's own limit; custom SMTP does not remove it)`);
      if (cfg2.emailRateLimitPerHour < AUTH_EMAILS_PER_RUN) {
        issues.push({
          severity: "medium",
          line: `the auth email rate limit is ${cfg2.emailRateLimitPerHour} per hour, below the ${AUTH_EMAILS_PER_RUN} accepted sends one run of the auth journeys needs: the sends beyond it are refused (HTTP 429)${cfg2.smtp?.configured ? ", custom SMTP included, because the limit is the provider's own" : ""}`,
          fix: `Raise it with \`auth.emailRateLimitPerHour\` in golive.yaml (30 is the provider's suggested starting point), then \`plan\` + \`apply\` \u2014 the \`auth:smtp\` step writes it with the custom SMTP when \`auth.smtp: resend\` \u2014 or raise the auth email rate limit in the ${provider} dashboard.`
        });
      }
    }
    if (!evidence.length) return skip(`${provider} does not report auth policy settings through its API (only the site URL and redirects are readable)`);
    if (missing.length) evidence.push(`not reported by ${provider}: ${missing.join(", ")}`);
    const sev = worst(issues.map((i) => i.severity));
    const lines = [...issues.map((i) => i.line), ...evidence];
    if (isFailing(sev)) return result("fail", sev, lines, issues.filter((i) => isFailing(i.severity)).map((i) => i.fix).join(" "));
    if (issues.length) return result("warn", sev, lines, issues.map((i) => i.fix).join(" "));
    return pass(lines);
  }
};

